import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-1-label';
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasW = 512;
  const atlasH = 512;
  const rect = { x: 0, y: 0, w: 512, h: 320 };

  const aspect = rect.w / rect.h;
  const planeHeight = 0.34;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const uOffset = uniform(vec2(rect.x / atlasW, 1 - (rect.y + rect.h) / atlasH));
  const uScale = uniform(vec2(rect.w / atlasW, rect.h / atlasH));

  let baseTexture = null;
  const handleTexture = (tex) => {
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.colorSpace = THREE.SRGBColorSpace;
    baseTexture = tex;
    const texNode = texture(tex, uv().mul(uScale).add(uOffset));
    material.map = texNode;
    material.needsUpdate = true;
  };

  try {
    const tex = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
    handleTexture(tex);
  } catch (e) {
    // fallback: flat surface color if texture load fails
    material.color = new THREE.Color('#0b0b10');
  }

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'label-plane';
  group.add(mesh);

  // Billboard behavior handled per-frame by ctx if it exposes camera; otherwise implement
  // a lightweight self-billboard using userData.update hook pattern if ctx supports it.
  group.userData.isBillboard = true;
  group.userData.update = (camera) => {
    if (camera) {
      group.quaternion.copy(camera.quaternion);
    }
  };

  // MSDF text: "Pricing 2" headline
  let textNode = null;
  try {
    textNode = ctx.fontAtlas.createText({
      text: 'Pricing 2',
      font: 'display',
      weight: 400,
      sizeEm: 0.34,
      color: '#e8ecf2',
      anchor: 'center',
    });
    textNode.position.set(0, 0, 0.001);
    group.add(textNode);
  } catch (e) {
    // if fontAtlas API differs, gracefully skip
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (baseTexture && baseTexture.dispose) baseTexture.dispose();
    if (textNode && textNode.userData && typeof textNode.userData.cleanup === 'function') {
      textNode.userData.cleanup();
    } else if (textNode) {
      textNode.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    }
    group.userData.handlers = {};
  };

  return group;
}
